export function createDriving({scene,camera,controls,onTravel,onExit}){
 const streetIndex=new SegmentIndex(),stepper=new FixedStepper();const collisions=new CollisionMap(),streets=[],keys=new Set(),touch=new Map();let dusk=false;const headlight=new T.SpotLight('#fff0ca',0,65,.5,.5,1.5);headlight.visible=false;scene.add(headlight,headlight.target);let destination=null;let enabled=false,view=0,check=0,lastRoad='',lastSurface='',audioInput={},saved,paused=false;const state={x:0,z:0,y:0,heading:0,speed:0,steer:0};
 const car=new T.Group();scene.add(car);car.visible=false;
 const paint=new T.MeshStandardMaterial({color:'#ea633e',roughness:.32,metalness:.35}),glass=new T.MeshStandardMaterial({color:'#203f4c',roughness:.2,metalness:.5}),rubber=new T.MeshStandardMaterial({color:'#111b20',roughness:1}),metal=new T.MeshStandardMaterial({color:'#b7c6cb',metalness:.7,roughness:.3});
 function box(w,h,d,x,y,z,m){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),m);mesh.position.set(x,y,z);car.add(mesh);return mesh;}
 box(1.85,.6,4.3,0,.86,0,paint);box(1.6,.65,2.15,0,1.43,-.25,glass);box(1.65,.12,2.2,0,1.8,-.25,paint);box(1.86,.18,.15,0,.59,2.17,metal);box(1.86,.18,.15,0,.59,-2.17,metal);
 for(const x of [-.62,.62]){box(.45,.18,.06,x,.91,2.18,new T.MeshBasicMaterial({color:'#fff1bd'}));box(.43,.15,.06,x,.91,-2.18,new T.MeshBasicMaterial({color:'#ff293b'}));}
 const wheels=[];for(const x of [-.96,.96])for(const z of [-1.35,1.35]){const wheel=new T.Group(),tire=new T.Mesh(new T.CylinderGeometry(.36,.36,.22,12),rubber),hub=new T.Mesh(new T.CylinderGeometry(.2,.2,.23,12),metal);tire.rotation.z=hub.rotation.z=Math.PI/2;wheel.add(tire,hub);wheel.position.set(x,.51,z);car.add(wheel);wheels.push({wheel,tire,hub,z});}
 const shadow=new T.Mesh(new T.CircleGeometry(2.7,32),new T.MeshBasicMaterial({color:'#09151b',transparent:true,opacity:.23,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.scale.x=.5;shadow.position.y=.15;car.add(shadow);
 const hud=document.createElement('section');hud.id='drive-hud';hud.hidden=true;hud.innerHTML='<div class="drive-top"><span>CHIȘINĂU / DRIVE</span><button id="drive-exit">Exit driving · Esc</button></div><div class="drive-speed"><strong id="speed">0</strong><span>km/h</span><b id="gear">D</b></div><div id="road-name">Finding a street…</div><div id="posted-speed"></div><div id="drive-destination"></div><div class="drive-actions"><button id="drive-camera">Camera · C</button><button id="drive-reset">Back to road · R</button></div><p>WASD / arrows · Space to brake · S to reverse</p><details id="drive-performance"><summary>Performance</summary><output id="drive-perf">Measuring…</output></details><div class="touch-drive"><div><button data-drive="left" aria-label="Steer left">◀</button><button data-drive="right" aria-label="Steer right">▶</button></div><div><button data-drive="reverse" aria-label="Reverse">REV</button><button data-drive="brake" aria-label="Brake">STOP</button><button data-drive="forward" aria-label="Accelerate">GO</button></div></div>';document.body.append(hud);
 const $=s=>document.querySelector(s);const clear=()=>{keys.clear();touch.clear();};
 function nearest(x,z){let best=null;for(const s of streetIndex.near(x,z,100)){const p=closest(x,z,s.a,s.b);if(!best||p.d<best.d)best={...p,s};}return best;}
 function place(x,z){const local=streetIndex.near(x,z,250);const candidates=(local.length?local:streets).map(s=>({...closest(x,z,s.a,s.b),s})).sort((a,b)=>a.d-b.d);for(const n of candidates){const h=Math.atan2(n.s.b[0]-n.s.a[0],n.s.b[1]-n.s.a[1]);const offset=n.s.oneway?0:Math.max(0,n.s.width/4-.25);n.x-=Math.cos(h)*offset;n.z+=Math.sin(h)*offset;const y=roadHeight(n.x,n.z,n.s.id);if([-1.35,0,1.35].some(o=>collisions.blocked(n.x+Math.sin(h)*o,n.z+Math.cos(h)*o,1.1,y)))continue;Object.assign(state,{x:n.x,z:n.z,y,heading:h,speed:0,steer:0});lastRoad=n.s.name;stepper.reset();return true;}return false;}
 function exit(){if(!enabled)return;enabled=false;headlight.intensity=0;headlight.visible=false;car.visible=false;hud.hidden=true;document.body.classList.remove('driving');clear();controls.enabled=true;camera.fov=saved.fov;camera.near=saved.near;camera.updateProjectionMatrix();controls.target.set(state.x,state.y,state.z);camera.position.set(state.x+160,state.y+200,state.z+240);onExit();}
 function start(x,z){if(!streets.length||!place(x,z))return false;saved={fov:camera.fov,near:camera.near};enabled=true;headlight.visible=dusk;car.visible=true;hud.hidden=false;document.body.classList.add('driving');controls.enabled=false;controls.autoRotate=false;camera.fov=65;camera.near=.15;camera.updateProjectionMatrix();clear();updateCamera(1,true);return true;}
 function updateCamera(dt,snap=false){const f=new T.Vector3(Math.sin(state.heading),0,Math.cos(state.heading)),p=new T.Vector3(state.x,state.y,state.z),offset=view===0?f.clone().multiplyScalar(-10-Math.abs(state.speed)*.07).add(new T.Vector3(0,4.8,0)):view===1?f.clone().multiplyScalar(1.6).add(new T.Vector3(0,1.9,0)):f.clone().multiplyScalar(-4).add(new T.Vector3(0,20,0));car.visible=view!==1;const desired=p.clone().add(offset);if(view===0){for(let t=.95;t>.2;t-=.1){const x=p.x+offset.x*t,z=p.z+offset.z*t;if(collisions.blocked(x,z,.25,state.y+3))desired.set(p.x+offset.x*Math.max(.15,t-.12),state.y+5,p.z+offset.z*Math.max(.15,t-.12));}}
 desired.y=Math.max(desired.y,heightAt(desired.x,desired.z)+1.8);camera.position.lerp(desired,snap?1:1-Math.exp(-7*dt));camera.lookAt(p.clone().add(f.multiplyScalar(view===1?22:5)).add(new T.Vector3(0,1.3,0)));}
 function cameraMode(){view=(view+1)%3;$('#drive-camera').textContent=['Chase · C','Bonnet · C','Overhead · C'][view];}
 $('#drive-exit').onclick=exit;$('#drive-camera').onclick=cameraMode;$('#drive-reset').onclick=()=>{place(state.x,state.z);updateCamera(1,true);};
 addEventListener('keydown',e=>{if(!enabled||/INPUT|SELECT|TEXTAREA/.test(e.target.tagName)||document.querySelector('dialog[open]'))return;const k=e.code;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyR','KeyC','Escape'].includes(k))e.preventDefault();keys.add(k);if(!e.repeat){if(k==='Escape')exit();if(k==='KeyC')cameraMode();if(k==='KeyR')$('#drive-reset').click();}});addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{clear();state.speed=0;stepper.reset();});document.addEventListener('visibilitychange',()=>{clear();state.speed=0;stepper.reset();});
 for(const b of hud.querySelectorAll('[data-drive]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch.set(e.pointerId,b.dataset.drive);};const up=e=>touch.delete(e.pointerId);b.onpointerup=up;b.onpointercancel=up;b.onlostpointercapture=up;}
 return {get audioState(){return {active:enabled,paused,speed:state.speed,throttle:audioInput.forward||audioInput.reverse,brake:audioInput.brake,surface:lastSurface};},setDusk(value){dusk=value;headlight.visible=value&&enabled;if(!value)headlight.intensity=0;},setDestination(value){destination=value;},get active(){return enabled;},start,exit,addBuilding(p,minHeight=0,height=Infinity){const base=buildingBase(p);p.minY=base+minHeight;p.maxY=base+height;collisions.add(p);},addWater(p,level=buildingBase(p)){p.minY=-Infinity;p.maxY=level+.5;collisions.add(p);},addRoad(e){if(e.tags.gameArea||e.tags.gameHidden||e.tags.area==='yes')return;if(!/^(motorway|trunk|primary|secondary|tertiary|residential|unclassified|living_street|service|motorway_link|trunk_link|primary_link|secondary_link|tertiary_link)$/.test(e.tags.highway))return;const p=e.geometry.map(project);if(e.tags.gameOneway==='-1')p.reverse();for(let i=1;i<p.length;i++)if(Math.hypot(p[i][0]-p[i-1][0],p[i][1]-p[i-1][1])>2){const segment={a:p[i-1],b:p[i],id:e.id,name:e.tags.name||'Unnamed street',speed:e.tags.maxspeed,surface:e.tags.surface,width:roadWidth(e.tags),oneway:['yes','1','-1'].includes(e.tags.gameOneway)};streets.push(segment);streetIndex.add(segment);}},update(dt){if(!enabled)return;const down=(...ks)=>ks.some(k=>keys.has(k)),held=a=>[...touch.values()].includes(a);paused=!!document.querySelector('dialog[open]');if(paused){clear();state.speed=0;stepper.reset();}const input={forward:!paused&&(down('KeyW','ArrowUp')||held('forward')),reverse:!paused&&(down('KeyS','ArrowDown')||held('reverse')),brake:down('Space')||held('brake'),steer:Number(down('KeyA','ArrowLeft')||held('left'))-Number(down('KeyD','ArrowRight')||held('right'))};audioInput=input;let hit=false;stepper.advance(dt,step=>{hit=stepCar(state,input,step,(x,z)=>{const y=driveHeight(x,z,state.y);return Math.abs(y-state.y)>1.4||collisions.blocked(x,z,1.1,y);})||hit;state.y=driveHeight(state.x,state.z,state.y);});car.position.set(state.x,state.y,state.z);const fx=Math.sin(state.heading),fz=Math.cos(state.heading),front=driveHeight(state.x+fx*1.35,state.z+fz*1.35,state.y),rear=driveHeight(state.x-fx*1.35,state.z-fz*1.35,state.y);car.rotation.set(0,state.heading,0);car.rotateX(-Math.atan2(front-rear,2.7));headlight.intensity=dusk?650:0;headlight.position.set(state.x+Math.sin(state.heading)*2,state.y+1,state.z+Math.cos(state.heading)*2);headlight.target.position.set(state.x+Math.sin(state.heading)*22,state.y+.3,state.z+Math.cos(state.heading)*22);for(const w of wheels){w.wheel.rotation.y=w.z>0?state.steer*.35:0;w.tire.rotation.x+=state.speed*dt/.36;w.hub.rotation.x=w.tire.rotation.x;}updateCamera(dt);$('#speed').textContent=Math.round(Math.abs(state.speed)*3.6);$('#gear').textContent=state.speed<-.1?'R':'D';check+=dt;if(check>.8){check=0;const n=nearest(state.x,state.z);lastRoad=n&&n.d<30?n.s.name:'Off road';lastSurface=n&&n.d<30?n.s.surface:'ground';const limit=n&&n.d<20?n.s.speed:null;$('#posted-speed').textContent=limit?'Mapped speed limit · '+limit+' (OSM)':'';onTravel(state.x,state.z);}if(destination){const dx=destination.x-state.x,dz=destination.z-state.z,dist=Math.hypot(dx,dz),angle=-(Math.atan2(dx,dz)-state.heading)*180/Math.PI;const dest=$('#drive-destination');if(!dest.firstChild){dest.append(document.createElement('span'),document.createTextNode(''));}const arrow=dest.firstChild;arrow.textContent='↑';arrow.style.cssText='display:inline-block;margin-right:10px;transform:rotate('+angle+'deg)';dest.lastChild.textContent=destination.name+' · '+(dist>1000?(dist/1000).toFixed(1)+' km':Math.round(dist)+' m')+' direct';}else $('#drive-destination').textContent='';$('#road-name').textContent=hit?'Obstacle · reverse or press R':lastRoad;}};
}
